package datawave.test.framework.generators.field;

import java.util.List;

/**
 * Generates the field names used by an ingest
 */
public interface FieldNameGenerator {

    /**
     * Generate N field names, appending to any field names generated by a previous call
     *
     * @param n
     *            the number of field names to generate
     */
    void generate(int n);

    /**
     * Get the field names that were generated
     *
     * @return an unmodifiable view of the generated field names
     */
    List<String> getFieldNames();

    /**
     * Get the field names in an order determined by the caller-supplied {@link java.util.Random}, so a shuffle is reproducible from the seed
     *
     * @return the list of field names in random order
     */
    List<String> getRandomizedFieldNames();

    /**
     * Flag that indicates if this generator produces numeric field names, that is, field names that require the JEXL identifier prefix
     *
     * @return true if the generated field names are numeric
     */
    boolean isNumeric();
}
